"use client";

import { useId, useState } from "react";

import { Button } from "@/components/ui/button";
import {
	Command,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandItem,
	CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import {
	BlocksIcon,
	BrainIcon,
	ChevronDownIcon,
	CpuIcon,
	DatabaseIcon,
	GlobeIcon,
	LayoutIcon,
	LineChartIcon,
	NetworkIcon,
	SearchIcon,
	ServerIcon,
} from "lucide-react";

const items = [
	{
		value: "analytics platform",
		label: "Analytics Platform",
		icon: LineChartIcon,
		number: 2451,
	},
	{
		value: "ai services",
		label: "AI Services",
		icon: BrainIcon,
		number: 1832,
	},
	{
		value: "database systems",
		label: "Database Systems",
		icon: DatabaseIcon,
		number: 1654,
	},
	{
		value: "compute resources",
		label: "Compute Resources",
		icon: CpuIcon,
		number: 943,
	},
	{
		value: "network services",
		label: "Network Services",
		icon: NetworkIcon,
		number: 832,
	},
	{
		value: "web services",
		label: "Web Services",
		icon: GlobeIcon,
		number: 654,
	},
	{
		value: "monitoring tools",
		label: "Monitoring Tools",
		icon: SearchIcon,
		number: 432,
	},
	{
		value: "server management",
		label: "Server Management",
		icon: ServerIcon,
		number: 321,
	},
	{
		value: "infrastructure",
		label: "Infrastructure",
		icon: BlocksIcon,
		number: 234,
	},
	{
		value: "frontend services",
		label: "Frontend Services",
		icon: LayoutIcon,
		number: 123,
	},
];

export default function Component() {
	const id = useId();
	const [open, setOpen] = useState<boolean>(false);
	const [value, setValue] = useState<string>("");

	return (
		<div className="not-first:*:mt-2">
			<Label htmlFor={id}>Options with icon and number</Label>
			<Popover open={open} onOpenChange={setOpen}>
				<PopoverTrigger asChild>
					<Button
						id={id}
						variant="outline"
						role="combobox"
						aria-expanded={open}
						className="bg-background hover:bg-background border-input w-full justify-between px-3 font-normal outline-offset-0 outline-hidden focus-visible:outline-[3px]"
					>
						{value ? (
							<span className="flex min-w-0 items-center gap-2">
								{(() => {
									const selectedItem = items.find(
										(item) => item.value === value
									);
									if (selectedItem) {
										const Icon = selectedItem.icon;
										return (
											<Icon className="text-muted-foreground size-4" />
										);
									}
									return null;
								})()}
								<span className="truncate">
									{items.find((item) => item.value === value)?.label}
								</span>
							</span>
						) : (
							<span className="text-muted-foreground">
								Select service category
							</span>
						)}
						<ChevronDownIcon
							size={16}
							className="text-muted-foreground/80 shrink-0"
							aria-hidden="true"
						/>
					</Button>
				</PopoverTrigger>
				<PopoverContent
					className="border-input w-full min-w-(--radix-popper-anchor-width) p-0"
					align="start"
				>
					<Command>
						<CommandInput placeholder="Search services..." />
						<CommandList>
							<CommandEmpty>No service found.</CommandEmpty>
							<CommandGroup>
								{items.map((item) => (
									<CommandItem
										key={item.value}
										value={item.value}
										onSelect={(currentValue) => {
											setValue(
												currentValue === value ? "" : currentValue
											);
											setOpen(false);
										}}
										className="flex items-center justify-between"
									>
										<div className="flex items-center gap-2">
											<item.icon className="text-muted-foreground size-4" />
											{item.label}
										</div>
										<span className="text-muted-foreground text-xs">
											{item.number.toLocaleString()}
										</span>
									</CommandItem>
								))}
							</CommandGroup>
						</CommandList>
					</Command>
				</PopoverContent>
			</Popover>
		</div>
	);
}

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

"use client";

import React from "react";

import { cn } from "@/lib/utils";
import * as LabelPrimitive from "@radix-ui/react-label";
import { cva, type VariantProps } from "class-variance-authority";

const labelVariants = cva(
	"text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
);

const Label = React.forwardRef<
	React.ElementRef<typeof LabelPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root> &
		VariantProps<typeof labelVariants>
>(({ className, ...props }, ref) => (
	<LabelPrimitive.Root
		ref={ref}
		className={cn(labelVariants(), className)}
		{...props}
	/>
));
Label.displayName = LabelPrimitive.Root.displayName;

export { Label };
